#!/bin/sh
editors_menu(){ while :; do c=$(ui_menu Editors 'Install and configure text editors.' wizards 'Selectable editor configuration wizards' scan 'Show installed editors' install 'Install editor bundle' default 'Set EDITOR/VISUAL' nano 'Configure Nano' vim 'Configure Vim' nvim 'Configure Neovim' micro 'Configure Micro' helix 'Configure Helix' alternatives 'System editor alternatives') || { _menu_rc=$?; [ "$_menu_rc" -eq "${UI_MENU_BACK_RC:-90}" ] && return 0; return "$_menu_rc"; }; case $c in wizards) editor_wizards_menu;; scan) for x in nano vim nvim vi micro hx helix emacs joe; do have "$x" && command -v "$x"; done >"$TMP_DIR/editors"; ui_text Editors "$(cat "$TMP_DIR/editors")";; install) p=$(ui_input Editors 'Packages:' 'nano vim neovim micro') || continue; run_capture Editors pkg_install $p;; default) e=$(ui_input Editor 'Command:' nano) || continue; replace_block "$CURRENT_HOME/.profile" editor "export EDITOR=$e\nexport VISUAL=$e";; nano) config_target_menu Nano "$CURRENT_HOME/.nanorc" nano_wizard nanorc;; vim) config_target_menu Vim "$CURRENT_HOME/.vimrc" vim_wizard vimrc;; nvim) nvim_full_wizard;; micro) micro_full_wizard;; helix) helix_full_wizard;; alternatives) have update-alternatives && as_root update-alternatives --config editor || ui_msg Alternatives 'update-alternatives not available.';; esac; done; }
